<script setup lang="ts">
import { ref } from 'vue'
import { Monitor, Plus } from '@element-plus/icons-vue'
import { api, post, remove, items, errorText } from '../api'
import { useLoad } from '../composables'
import { ElMessage, ElMessageBox } from 'element-plus'
const rows=ref<any[]>([]),name=ref(''),dialog=ref(false),saving=ref(false),formError=ref('')
const {loading,error,load}=useLoad(async()=>{rows.value=items(await api('/devices?size=200'))})
async function authorize(){if(!name.value.trim()){formError.value='请为当前浏览器填写一个容易识别的名称';return}saving.value=true;formError.value='';try{await post('/devices',{name:name.value.trim()});dialog.value=false;name.value='';ElMessage.success('本浏览器已授权，可以退出管理员账号并进入公共打卡页');load()}catch(e){formError.value=errorText(e)}finally{saving.value=false}}
async function revoke(row:any){try{await ElMessageBox.confirm(`撤销「${row.name}」后，该浏览器立即失去公共打卡权限。`,'撤销设备授权',{type:'warning',confirmButtonText:'撤销授权',cancelButtonText:'取消'});await remove(`/devices/${row.id}`);ElMessage.success('设备授权已撤销');load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(errorText(e))}}
</script>
<template><div class="page-head"><div><div class="eyebrow">AUTHORIZED KIOSKS</div><h1>打卡设备</h1><p>授权本浏览器作为公共打卡入口，有效期默认 7 天。</p></div><el-button type="primary" :icon="Plus" @click="dialog=true;formError=''">授权本浏览器</el-button></div><div class="welcome-banner"><div><h2>让公共打卡设备准备就绪</h2><p>在目标设备登录管理员账号 → 授权当前浏览器 → 退出管理员账号 → 进入公共打卡页。</p></div><el-icon class="welcome-art"><Monitor/></el-icon></div><div class="panel"><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-table :data="rows" v-loading="loading" empty-text="暂无设备授权，请先授权当前浏览器"><el-table-column prop="name" label="设备名称" min-width="200"/><el-table-column prop="createdAt" label="授权时间" min-width="185"/><el-table-column prop="expiresAt" label="有效期至" min-width="185"/><el-table-column label="状态" width="110"><template #default="{row}"><el-tag :type="row.revoked?'info':new Date(row.expiresAt)<new Date()?'warning':'success'">{{row.revoked?'已撤销':new Date(row.expiresAt)<new Date()?'已过期':'已授权'}}</el-tag></template></el-table-column><el-table-column label="操作" width="120"><template #default="{row}"><el-button text type="danger" :disabled="row.revoked" @click="revoke(row)">撤销授权</el-button></template></el-table-column></el-table></div><p class="footnote">设备凭据使用安全 Cookie，仅授予打卡权限。授权绑定当前浏览器，不能作为硬件设备认证；清除 Cookie 后需要重新授权。</p><el-dialog v-model="dialog" title="授权本浏览器" width="470px"><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><el-form label-position="top" @submit.prevent="authorize"><el-form-item label="设备名称"><el-input v-model="name" placeholder="例如：一楼前台 · Chrome" maxlength="80"/></el-form-item></el-form><p class="help-text">请在实际用于打卡的电脑或手机上执行本操作。此授权仅在当前浏览器中生效。</p><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="authorize">确认授权</el-button></template></el-dialog></template>
